import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("logistics")

DATABASE_PATH = "logistics.db"


@mcp.tool()
def get_shipment_tracking_history(tracking_number: str, max_events: int = 50) -> dict:
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        shipment_row_found_for_tracking_number = database_connection.execute(
            "SELECT id, carrier, status, origin, destination FROM shipments WHERE tracking_number = ?",
            (tracking_number,),
        ).fetchone()
        if shipment_row_found_for_tracking_number is None:
            return {"error": "Shipment not found", "tracking_number": tracking_number}
        scan_event_rows_for_shipment = database_connection.execute(
            "SELECT event_time, location, description FROM scan_events WHERE shipment_id = ? ORDER BY event_time ASC LIMIT ?",
            (shipment_row_found_for_tracking_number["id"], max_events),
        ).fetchall()
        list_of_scan_events_as_dictionaries = [dict(single_row) for single_row in scan_event_rows_for_shipment]
        return {
            "tracking_number": tracking_number,
            "carrier": shipment_row_found_for_tracking_number["carrier"],
            "status": shipment_row_found_for_tracking_number["status"],
            "origin": shipment_row_found_for_tracking_number["origin"],
            "destination": shipment_row_found_for_tracking_number["destination"],
            "events": list_of_scan_events_as_dictionaries,
        }
    finally:
        database_connection.close()

import sqlite3
from datetime import datetime, timedelta, timezone

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("logistics")

DATABASE_PATH = "logistics.db"
ALLOWED_ACCESS_LEVELS = ("view", "edit")


@mcp.tool()
def grant_customs_portal_access_for_shipment(
    shipment_reference: str,
    broker_email: str,
    access_level: str = "view",
    duration_days: int = 14,
) -> dict:
    if access_level not in ALLOWED_ACCESS_LEVELS:
        return {"error": "access_level must be one of: view, edit"}
    if duration_days < 1 or duration_days > 90:
        return {"error": "duration_days must be between 1 and 90"}
    database_connection = sqlite3.connect(DATABASE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        shipment_record_for_reference = database_connection.execute(
            "SELECT id, status, origin, destination FROM shipments WHERE reference = ?",
            (shipment_reference,),
        ).fetchone()
        if shipment_record_for_reference is None:
            return {"error": "Shipment not found"}
        if shipment_record_for_reference["status"] != "customs_clearance":
            return {
                "error": "Shipment is not in customs clearance",
                "status": shipment_record_for_reference["status"],
            }
        broker_user_record = database_connection.execute(
            "SELECT id FROM portal_users WHERE email = ? AND role = 'broker'",
            (broker_email,),
        ).fetchone()
        if broker_user_record is None:
            return {"error": "No broker account found for that email"}
        access_expiry_timestamp = datetime.now(timezone.utc) + timedelta(days=duration_days)
        database_connection.execute(
            "INSERT OR REPLACE INTO shipment_document_access (shipment_id, user_id, access_level, expires_at) VALUES (?, ?, ?, ?)",
            (
                shipment_record_for_reference["id"],
                broker_user_record["id"],
                access_level,
                access_expiry_timestamp.isoformat(),
            ),
        )
        database_connection.commit()
        return {
            "shipment_reference": shipment_reference,
            "origin": shipment_record_for_reference["origin"],
            "destination": shipment_record_for_reference["destination"],
            "broker_email": broker_email,
            "access_level": access_level,
            "expires_at": access_expiry_timestamp.isoformat(),
        }
    finally:
        database_connection.close()

import sqlite3

from agents import function_tool as tool

DATABASE_PATH = "logistics.db"


@tool
def move_shipment_to_warehouse_bin(shipment_id: int, target_bin_code: str) -> str:
    if shipment_id <= 0:
        return "Error: shipment_id must be positive"
    if not target_bin_code or not target_bin_code.strip():
        return "Error: target_bin_code is required"
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        bin_row = connection.execute("SELECT id FROM bins WHERE code = ?", (target_bin_code.strip(),)).fetchone()
        if bin_row is None:
            return "Error: target bin not found"
        cursor = connection.execute("UPDATE inventory SET bin_id = ? WHERE shipment_id = ?", (bin_row[0], shipment_id))
        if cursor.rowcount == 0:
            return "Error: shipment not in inventory"
        connection.commit()
        return f"Shipment {shipment_id} moved to bin {target_bin_code.strip()}"
    finally:
        connection.close()
